PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, source_type TEXT NOT NULL, organization TEXT NOT NULL, title TEXT NOT NULL, dataset_id TEXT, canonical_url TEXT NOT NULL, retrieved_at TEXT, coverage_start TEXT, coverage_end TEXT, license TEXT, description TEXT, citation TEXT, checksum TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS ingestion_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, source_id TEXT NOT NULL REFERENCES sources(id), started_at TEXT NOT NULL, completed_at TEXT, records_received INTEGER DEFAULT 0, records_inserted INTEGER DEFAULT 0, records_updated INTEGER DEFAULT 0, records_rejected INTEGER DEFAULT 0, status TEXT NOT NULL, code_version TEXT);
CREATE TABLE IF NOT EXISTS boundary_versions (id TEXT PRIMARY KEY, name TEXT NOT NULL, effective_start_year INTEGER, effective_end_year INTEGER, source_id TEXT REFERENCES sources(id), description TEXT, geometry_path TEXT, confidence TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS neighborhoods (id TEXT PRIMARY KEY, canonical_slug TEXT NOT NULL UNIQUE, canonical_name TEXT NOT NULL, current_sna_name TEXT, current_sna_number INTEGER, active INTEGER DEFAULT 1, notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS neighborhood_aliases (id INTEGER PRIMARY KEY AUTOINCREMENT, neighborhood_id TEXT NOT NULL REFERENCES neighborhoods(id), alias TEXT NOT NULL, source_system TEXT, start_year INTEGER, end_year INTEGER, confidence TEXT NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS offense_categories (id TEXT PRIMARY KEY, label TEXT NOT NULL, group_name TEXT NOT NULL, part1_flag INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS source_offense_mappings (id INTEGER PRIMARY KEY AUTOINCREMENT, source_system TEXT NOT NULL, source_code TEXT, source_label TEXT NOT NULL, canonical_offense_id TEXT REFERENCES offense_categories(id), valid_from TEXT, valid_to TEXT, mapping_version TEXT NOT NULL, mapping_confidence TEXT NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS crime_events (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), source_system TEXT NOT NULL, source_record_id TEXT NOT NULL, incident_number TEXT, date_reported TEXT, date_from TEXT, date_to TEXT, year_reported INTEGER, canonical_offense_id TEXT REFERENCES offense_categories(id), source_offense_label TEXT, neighborhood_id TEXT REFERENCES neighborhoods(id), source_neighborhood_name TEXT, police_district TEXT, beat TEXT, latitude REAL, longitude REAL, geography_confidence TEXT, source_payload_json TEXT, ingestion_run_id INTEGER REFERENCES ingestion_runs(id), created_at TEXT NOT NULL, UNIQUE(source_system, source_record_id));
CREATE TABLE IF NOT EXISTS population_estimates (id INTEGER PRIMARY KEY AUTOINCREMENT, neighborhood_id TEXT NOT NULL REFERENCES neighborhoods(id), year INTEGER NOT NULL, population INTEGER NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), boundary_version_id TEXT REFERENCES boundary_versions(id), method TEXT NOT NULL, confidence TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS crime_daily_neighborhood (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, neighborhood_id TEXT NOT NULL REFERENCES neighborhoods(id), offense_category_id TEXT NOT NULL REFERENCES offense_categories(id), count INTEGER NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), generated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS crime_monthly_neighborhood (id INTEGER PRIMARY KEY AUTOINCREMENT, year INTEGER NOT NULL, month INTEGER NOT NULL, neighborhood_id TEXT NOT NULL REFERENCES neighborhoods(id), offense_category_id TEXT NOT NULL REFERENCES offense_categories(id), count INTEGER NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), generated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS crime_annual_neighborhood (id INTEGER PRIMARY KEY AUTOINCREMENT, year INTEGER NOT NULL, neighborhood_id TEXT NOT NULL REFERENCES neighborhoods(id), boundary_version_id TEXT REFERENCES boundary_versions(id), offense_category_id TEXT NOT NULL REFERENCES offense_categories(id), count INTEGER NOT NULL, population INTEGER, rate_per_1000 REAL, source_quality TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), is_complete_year INTEGER NOT NULL, coverage_start TEXT, coverage_end TEXT, generated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS historical_aggregate_imports (id INTEGER PRIMARY KEY AUTOINCREMENT, imported_at TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), file_path TEXT NOT NULL, records_received INTEGER NOT NULL, records_rejected INTEGER NOT NULL, status TEXT NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS validation_results (id INTEGER PRIMARY KEY AUTOINCREMENT, validation_type TEXT NOT NULL, status TEXT NOT NULL, generated_at TEXT NOT NULL, details_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS crime_events_date_neighborhood_idx ON crime_events(date_reported, neighborhood_id);
CREATE INDEX IF NOT EXISTS crime_daily_lookup_idx ON crime_daily_neighborhood(date, neighborhood_id, offense_category_id);
